/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'reassignmentStatus',
		value: {
			...api.state.reassignmentStatus,
			status: 'success'
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const taskId = api.context.props.sysId;
    const invalidTask = api.data.validate_attestation_task_review.output.invalidTask;
    const userNotAssigned = api.data.validate_attestation_task_review.output.userNotAssigned;
	const userNotWithinGroup = api.data.validate_attestation_task_review.output.userNotWithinGroup;

    if (!invalidTask && userNotAssigned && !userNotWithinGroup) {
        return {
            route: 'attestation-task',
            fields: {
                'sysId': taskId
            },
            params: null,
            redirect: null,
            passiveNavigation: null,
            title: null,
            multiInstField: null,
            targetRoute: null,
            external: null
        };
    }
}
